args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?grandmother ?grandmotherLabel WHERE {
  dbr:John_III,_Duke_of_Cleves dbo:parent ?father .
  ?father dbo:parent ?grandmother .
  OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel FILTER (lang(?grandmotherLabel) = "en") }
}

